package com.crm.fees.controller;import com.crm.fees.service.FeeBillingCandidates;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;
@RestController @RequestMapping("/api/fees/billing-candidates") public class FeeBillingController {private final FeeBillingCandidates service;public FeeBillingController(FeeBillingCandidates s){service=s;}@GetMapping public ResponseEntity<?> list(@RequestParam String customerId,@RequestParam String currency,@RequestParam(defaultValue="0") int page){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.list(customerId,currency,page));}@GetMapping("/{id}") public ResponseEntity<?> get(@PathVariable long id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.get(id));}}
